List.forall_zipWith.{u, u_1, u_2} {α : Type u} {β : Type u_1} {γ : Type u_2} {f : α → β → γ} {p : γ → Prop}
  {l₁ : List α} {l₂ : List β} :
  l₁.length = l₂.length → (List.Forall p (List.zipWith f l₁ l₂) ↔ List.Forall₂ (fun x y => p (f x y)) l₁ l₂)

List.zipWith_zipWith_left.{u, u_1, u_2, u_3, u_4} {α : Type u} {β : Type u_1} {γ : Type u_2} {δ : Type u_3}
  {ε : Type u_4} (f : δ → γ → ε) (g : α → β → δ) (la : List α) (lb : List β) (lc : List γ) :
  List.zipWith f (List.zipWith g la lb) lc = List.zipWith3 (fun a b c => f (g a b) c) la lb lc
